import React from "react";
import "./IncomeCategory.css";

function IncomeCategory({ onNext }) {

  const handleSelect = (value) => {
    onNext(value);
  };

  return (
    <div className="income-container">
      <h1 className="income-title">Select Your Income Category</h1>
      <p className="income-subtitle">
        Choose the option that best describes your income
      </p>

      <div className="income-grid">

        <div className="income-card" onClick={() => handleSelect("No Income")}>
          <div className="income-icon">💸</div>
          <div className="income-name">No Income</div>
          <div className="income-desc">No regular income source</div>
        </div>

        <div className="income-card" onClick={() => handleSelect("Low Income")}>
          <div className="income-icon">💰</div>
          <div className="income-name">Low Income</div>
          <div className="income-desc">Below ₹25,000/month</div>
        </div>

        <div className="income-card" onClick={() => handleSelect("Medium Income")}>
          <div className="income-icon">📈</div>
          <div className="income-name">Medium Income</div>
          <div className="income-desc">₹25,000 - ₹75,000/month</div>
        </div>

        <div className="income-card" onClick={() => handleSelect("High Income")}>
          <div className="income-icon">🏆</div>
          <div className="income-name">High Income</div>
          <div className="income-desc">Above ₹75,000/month</div>
        </div>

      </div>
    </div>
  );
}

export default IncomeCategory;
